UNITS = []

UNITS.append(dict(id="N7", part="National", title="Transfer of Title, Deeds, Title Insurance & Closing",
 objectives=["Identify voluntary and involuntary transfers","Compare deed types and required elements","Explain recording, notice and title evidence","Walk through closing, prorations and settlement"],
 lessons=[
 dict(title="Deeds and methods of transfer",
  body=["**Title** is the right to ownership; **deed** is the instrument that conveys it.",
  "**Essential elements of a valid deed**: (1) grantor with legal capacity, (2) identifiable grantee, (3) words of conveyance (granting clause), (4) adequate property description, (5) consideration recited (often nominal), (6) signed by the grantor, (7) **delivery and acceptance** (the deed is not effective until delivered with intent to pass title), and in most states acknowledged (notarized) to be recorded. A deed is valid even if not recorded; recording gives *constructive notice*.",
  "**Types of deeds**:",
  "- **General warranty deed** — the greatest protection: covenants of seisin, right to convey, against encumbrances, quiet enjoyment, warranty forever; warranties cover the *entire history* of title.",
  "- **Special warranty deed** — warrants only against defects arising during the grantor's ownership.",
  "- **Quitclaim deed** — conveys whatever interest the grantor has, **no warranties**; used to clear clouds on title.",
  "- **Bargain and sale deed** — implies the grantor owns but offers no warranty against encumbrances.",
  "- **Trustee's deed** (foreclosure), **sheriff's deed**, **executor's/administrator's deed**, **deed of gift**.",
  "**Voluntary alienation**: sale, gift, will. **Involuntary**: foreclosure, eminent domain, **adverse possession** (actual, open and notorious, hostile, exclusive, continuous for the statutory period—and in some states payment of taxes), escheat, bankruptcy, partition. **Descent** (intestate succession) transfers title by law to heirs; **testate** = with a will; **probate** validates the will. **Title by accession**: accretion, avulsion."],
  key=["Delivery and acceptance make a deed effective","General warranty = broadest; quitclaim = no warranty","Recording gives constructive notice, not validity"],
  example="Grandpa signs a deed and puts it in a drawer, intending it to pass at death. Without present delivery, no transfer occurs."),
 dict(title="Recording, title evidence and title insurance",
  body=["**Recording** places a document in the public record, in the county where the land lies, to give **constructive notice** to the world and establish **priority**. Most states are **race-notice** or **notice** jurisdictions. A buyer in possession gives **actual notice**. **Chain of title** is the history of ownership; a **title search** runs through it; an **abstract of title** summarizes recorded documents with an **attorney's opinion**; a **cloud on title** is a claim that might impair ownership (cured by a quitclaim deed or **quiet title** suit).",
  "**Title insurance** protects against defects that existed at the policy date but were unknown. One premium at closing. **Owner's policy** protects the buyer for as long as they or heirs hold the property; **lender's policy** protects the lender up to the loan balance and is nearly always required. **Standard coverage** excludes matters that a survey or inspection would show, plus zoning, easements not of record, and known defects. **Extended coverage (ALTA)** requires a survey and covers more.",
  "**Marketable title** is free from reasonable doubt; the buyer need not accept anything less. **Insurable title** can be insured even with exceptions.",
  "**Torrens system** — a government-guaranteed registration system, rare in the U.S. **Homestead** laws protect a portion of the home's equity from creditors."],
  key=["Recording = constructive notice; possession = actual (inquiry) notice","Title insurance covers hidden past defects, not future ones","Standard policy excludes survey matters"],
  example="A forged deed in the chain of title surfaces after closing. The owner's title policy defends the claim and covers loss up to the policy amount."),
 dict(title="Closing, settlement and prorations",
  body=["**Closing** (settlement) is the final step: documents signed, funds disbursed, deed delivered, loan recorded. It may be held by an attorney, title company or escrow agent. **Escrow** means a neutral party holds documents and funds until conditions are met (**delivery in escrow** makes the deed effective on satisfaction of conditions).",
  "**Typical steps**: final walk-through, review of Closing Disclosure, payoff of seller's liens, deed and lien recording, disbursements, commission payment.",
  "**Prorations** adjust for items that belong to buyer or seller by closing date: property taxes, insurance, HOA dues, rents (and security deposits transferred), interest on assumed loans, utilities. **Conventions**: taxes are generally paid in arrears (seller owes up to closing); unless otherwise stated, a **statutory year** uses 360 days (30-day months), while a **calendar year** uses actual days; **the buyer owns the closing day** unless the contract says otherwise; interest on loans is paid in arrears.",
  "**Debits and credits**: A **debit** is an amount a party owes; a **credit** is an amount that reduces what they owe or that they receive. For the buyer: purchase price (debit), earnest money (credit), loan amount (credit), seller credits (credit), prepaid taxes owed to seller (debit), points and fees (debit). For the seller: sale price (credit), payoff (debit), commission (debit), taxes owed (debit).",
  "**Post-closing**: recording, title policy issuance, delivery of keys. **Wire fraud** is a leading closing risk—verify wiring instructions by phone using a known number; never email account numbers; warn clients early."],
  key=["Buyer owns the closing day unless contract says otherwise","Property taxes usually paid in arrears → seller owes buyer a credit","Verify wiring instructions by phone"],
  example="Annual tax $2,400 unpaid at a June 30 closing under a 360-day year: seller owes 6 months → $1,200 credited to the buyer."),
 ],
 quiz=[
 ("A deed becomes effective upon:", "delivery and acceptance", ["signing only","recording only","notarization only"], "Delivery with intent."),
 ("The deed giving the broadest protection is the:", "general warranty deed", ["quitclaim deed","special warranty deed","bargain and sale deed"], "Covers full chain of title."),
 ("A quitclaim deed:", "conveys whatever interest the grantor has, without warranties", ["warrants the title","guarantees against encumbrances","can only be used by the government"], "No warranty."),
 ("Recording a deed gives:", "constructive notice", ["actual notice only","title insurance","warranty"], "Notice to the world."),
 ("A claim that may impair title is a:", "cloud on title", ["covenant","easement in gross","novation"], "Cure by quiet title or quitclaim."),
 ("Adverse possession requires possession that is:", "open, notorious, hostile, exclusive and continuous", ["secret and occasional","permitted by the owner","shared with the owner"], "Elements."),
 ("An owner's title policy generally covers:", "hidden defects that existed at policy date", ["future liens created by the owner","physical defects","market decline"], "Past defects."),
 ("Standard coverage title insurance generally excludes:", "matters a survey would reveal", ["forgeries","recorded liens","undisclosed heirs"], "Need extended coverage and a survey."),
 ("At closing, the buyer's earnest money is shown as a:", "credit", ["debit","proration","commission"], "Reduces the cash due."),
 ("Taxes unpaid at closing are generally:", "a credit to the buyer and debit to the seller", ["a debit to the buyer","ignored","a seller credit"], "Seller owes accrued taxes."),
 ("Under common proration conventions, the closing day belongs to the:", "buyer", ["seller","lender","title company"], "Unless contract says otherwise."),
 ("The best protection against wire fraud is to:", "verify wiring instructions by phone using a known number", ["email the instructions","text account numbers","accept new instructions by email"], "Call back."),
 ("Transfer by will is called:", "testate succession", ["descent","escheat","accretion"], "Will = testate."),
 ("A statutory year in prorations uses:", "360 days", ["365 days","366 days","400 days"], "30-day months."),
 ]))

UNITS.append(dict(id="N8", part="National", title="Practice of Real Estate: Fair Housing, Disclosure & Ethics",
 objectives=["Apply the Fair Housing Act and ADA","Avoid discriminatory advertising, steering and blockbusting","Handle trust funds, antitrust, disclosure and technology risk"],
 lessons=[
 dict(title="Fair housing and anti-discrimination",
  body=["The **Fair Housing Act (Title VIII, Civil Rights Act of 1968, as amended 1988)** prohibits discrimination in sale, rental, financing and advertising based on **race, color, religion, sex, national origin, familial status (children under 18, pregnant women, those securing custody), and disability**. The **Civil Rights Act of 1866** bans race discrimination in all property transactions with **no exemptions** (*Jones v. Mayer*). **Sexual orientation and gender identity** protections come from some state/local laws and HUD policy that has varied; confirm current enforcement.",
  "**Prohibited practices**: **steering** (guiding buyers toward or away from areas), **blockbusting/panic peddling** (inducing sales by claiming minority entry will reduce values), **redlining** (refusing loans or insurance by area), discriminatory advertising, refusing to show/sell/rent, different terms, **refusing reasonable accommodations or modifications for disabled persons**, retaliation. 'Adult only,' 'no children,' 'perfect for single professionals' are problematic.",
  "**Exemptions** (Fair Housing Act): **sale of a single-family home by an owner** who owns ≤3 houses, uses no broker and no discriminatory advertising; **rental of rooms in an owner-occupied building with ≤4 units** (Mrs. Murphy); **religious organizations** and **private clubs** (limited to members); **housing for older persons** (55+ with at least 80% of units having one occupant 55+ and an intent to operate as such, or 62+ housing). Brokers can't use exemptions.",
  "**Disability**: landlords must permit **reasonable modifications** (at the tenant's expense in private housing) and make **reasonable accommodations** in rules (e.g., assistance animals). New multifamily construction (4+ units, first occupancy after March 1991) must meet design standards. **ADA** Title III requires public accommodations (including a broker's office) to be accessible.",
  "**Enforcement**: complaint to HUD within **1 year**, or lawsuit in court within **2 years**. HUD may refer to an administrative law judge; penalties include actual damages, injunctions, civil penalties (adjusted annually), and attorney's fees. **Testers** and the *Fair Housing Congress* approach (audits) are used.",
  "**Advertising rule**: describe the property, not the preferred occupant. Use the Equal Housing Opportunity logo/statement. **Describe, don't characterize** neighborhoods. **Treat all clients the same**."],
  key=["Seven federally protected classes under FHA","Familial status protects households with children under 18","Civil Rights Act of 1866 has no exemptions and covers race"],
  example="An agent tells a family with kids, 'You'd like the east side, it has more families.' That is steering. Provide the same listings to everyone who meets criteria."),
 dict(title="Disclosure, trust funds, antitrust and technology",
  body=["**Material facts**: facts that would influence a reasonable buyer's decision (structural defects, flooding, zoning, liens). **Stigmatized property** (death, crime, haunted) disclosures are state-specific; most states don't require agents to disclose deaths/crimes/HIV status, and HIV/AIDS status is **never** to be disclosed. **Megan's Law** sex-offender data is public, and agents should refer to official registries rather than advise. **Seller property condition disclosure** is required in many states; **'as is'** doesn't excuse fraud or concealment of known latent defects.",
  "**Trust funds**: **Commingling** (mixing client funds with the broker's own) and **conversion** (using client funds) are serious violations. Keep a separate trust account, keep records, reconcile monthly, and release only per the contract or a written agreement/court order.",
  "**Antitrust** — Sherman Act: **price fixing**, **group boycotts**, **tie-in arrangements**, **market allocation** are illegal and can bring criminal penalties. Commissions are never set by law or association.",
  "**Unauthorized practice of law** — licensees may fill in approved blanks on **standard forms**, but not draft contracts or give legal advice; when in doubt, refer to an attorney.",
  "**Advertising**: must be truthful, include the broker's name (as licensed) clearly, and not mislead; salespeople can't advertise on their own without broker identification and approval.",
  "**Technology & privacy**: TCPA/Do Not Call, CAN-SPAM, **Gramm-Leach-Bliley** safeguards for consumer financial data, **wire fraud**, e-signatures valid under **E-SIGN/UETA**, social media compliance, and cyber hygiene.",
  "**Ethics**: **Realtor® Code of Ethics** (NAR) — duties to clients, customers, public and other Realtors®; arbitration of disputes between members. A license is not the same as membership in NAR.",
  ],
  key=["Never disclose HIV/AIDS status","'As is' doesn't protect against concealed latent defects","Commingling = mixing funds; conversion = using them"],
  example="A broker deposits an earnest check into the office operating account to cover payroll for a week. That is commingling and conversion."),
 ],
 quiz=[
 ("Which is NOT a federally protected class?", "age", ["familial status","disability","national origin"], "Age is not among the seven."),
 ("Familial status protects:", "households with children under 18", ["married couples only","seniors","veterans"], "Includes pregnant women."),
 ("Steering is:", "guiding buyers toward or away from areas based on a protected class", ["a lawful marketing practice","showing every listing","an exemption"], "Illegal."),
 ("Blockbusting is:", "inducing panic selling by suggesting protected-class entry will lower values", ["a loan practice","lawful advertising","a title issue"], "Illegal."),
 ("The Civil Rights Act of 1866 covers:", "race discrimination in all property transactions", ["only rentals","only sales by brokers","religion only"], "No exemptions."),
 ("A homeowner selling their single-family home without a broker or discriminatory ads may qualify for:", "an exemption under the Fair Housing Act", ["an exemption under the 1866 Act","no exemption ever","tax-free sale"], "Limited exemption."),
 ("A tenant with a disability asks to install a ramp. The landlord must generally:", "permit reasonable modifications, usually at the tenant's expense", ["refuse","pay for it always","evict"], "FHA requirement."),
 ("An HUD complaint must be filed within:", "1 year", ["30 days","6 months","5 years"], "Court action is 2 years."),
 ("Advertising 'no children' is:", "a violation based on familial status", ["permitted","required for seniors","a rental standard"], "Unless qualifying housing for older persons."),
 ("Mixing client money with the broker's funds is:", "commingling", ["conversion","escrow","proration"], "Commingling."),
 ("Using client funds for personal use is:", "conversion", ["commingling","a lawful loan","a proration"], "Conversion."),
 ("An agent should disclose a buyer's HIV status:", "never", ["always","upon request","to the lender"], "Must not disclose."),
 ("Price fixing is a violation of the:", "Sherman Antitrust Act", ["Fair Housing Act","RESPA","TILA"], "Antitrust."),
 ("Licensees may:", "complete blanks on approved forms", ["draft custom contracts","give legal advice","interpret contracts as an attorney"], "UPL limits."),
 ("The Equal Housing Opportunity logo in an ad shows:", "a commitment to fair housing", ["a tax exemption","board membership","a discount"], "Required good practice."),
 ]))

UNITS.append(dict(id="N9", part="National", title="Leases, Property Management & Specialty Areas",
 objectives=["Write and interpret leases","Explain landlord and tenant duties and remedies","Understand property management roles and specialty property types"],
 lessons=[
 dict(title="Leases and landlord-tenant fundamentals",
  body=["A **lease** conveys possession and use (a leasehold estate) for consideration (rent). The **landlord/lessor** retains the **reversionary interest**; the **tenant/lessee** holds the leasehold. Leases over one year must generally be in writing (statute of frauds).",
  "**Types of leases**: **gross** (landlord pays operating expenses), **net / single-net / double-net / triple-net (NNN)** (tenant pays some or all taxes, insurance, maintenance), **percentage** (rent = base + % of tenant's gross sales), **graduated** (scheduled increases), **index** (tied to an index), **ground lease** (tenant leases land and builds improvements; long-term, typically 50–99 years), **sandwich lease** (a sublessor stands between the owner and the occupant).",
  "**Assignment** transfers the tenant's entire interest; **sublease** transfers part (partial space or term) with the original tenant remaining liable; both usually require landlord consent.",
  "**Landlord duties**: deliver possession, quiet enjoyment, maintain habitability (**implied warranty of habitability** in residential leases), and follow fair housing laws. **Tenant duties**: pay rent, care for premises, avoid waste. **Constructive eviction** — the tenant moves out because the landlord's failure makes the premises uninhabitable; the tenant's rent duty ends if they vacate. **Retaliatory eviction** is illegal in many states. **Actual eviction** requires a court process; self-help (changing locks, shutting off utilities) is generally illegal.",
  "**Security deposits** are held per statute; states regulate how long to return the deposit and itemization.",
  "**Lease termination**: expiration, surrender and acceptance, mutual agreement, breach, destruction of property, eminent domain. Death of either party does not automatically end a lease; **foreclosure** may (depending on law and notice). A sale doesn't end a lease. **Estoppel certificate** confirms lease terms to a buyer or lender."],
  key=["Triple-net: tenant pays taxes, insurance and maintenance","Constructive eviction needs the landlord's failure plus the tenant vacating","Self-help eviction is generally illegal"],
  example="A retail lease sets base rent $4,000/month plus 5% of gross sales over $600,000/year. That is a percentage lease with a breakpoint."),
 dict(title="Property management and specialty areas",
  body=["A **property manager** is an agent of the owner under a **management agreement**: duties include renting, collecting rent, maintaining the property, hiring vendors, budgeting, accounting, reporting. Compensation is usually a percentage of collected rent plus leasing fees. The owner sets policies; the manager follows instructions and keeps trust accounts separate. In many states a property manager must hold a real estate license.",
  "**Budgets and reports**: **operating budget**, **reserves**, **owner statements**, **rent roll**, **vacancy/turnover cost**. **Maintenance types**: preventive, routine, emergency, deferred, capital improvements.",
  "**Tenant selection** must follow fair housing law; use consistent written criteria and screening for all applicants.",
  "**Specialty and property types**: residential (1–4 units, multifamily), commercial (office, retail, hospitality), industrial, agricultural, special purpose. **Subdivision & development**, **land use**: platting, utilities, zoning, impact studies. **Farms/ranches**: water rights, mineral rights, soil, crop-share leases. **Timber, coastal and flood-prone land**: easements and regulation. **Commercial** metrics: cap rate, NOI, DSCR, vacancy, CAM charges.",
  "**Insurance basics**: homeowner's policy forms (HO-3 covers an open-peril dwelling and named-peril personal property); **coinsurance** (80% rule penalizes underinsurance); **flood insurance** is separate; **replacement cost vs actual cash value**; **liability coverage**.",
  "**Home inspections** and **warranties** manage buyer risk, but do not replace seller disclosure."],
  key=["Property manager is an agent bound by the management agreement","Coinsurance penalty applies when insured below the required % of value","HO-3 covers dwelling on open-peril basis"],
  example="Replacement cost $300,000; policy requires 80% ($240,000) but owner carries $180,000; a $20,000 loss pays 180/240 × $20,000 = $15,000."),
 ],
 quiz=[
 ("A lease where the tenant pays taxes, insurance and maintenance is a:", "triple-net lease", ["gross lease","graduated lease","sandwich lease"], "NNN."),
 ("Rent that increases on a pre-set schedule is a:", "graduated lease", ["percentage lease","gross lease","net listing"], "Graduated."),
 ("A tenant who transfers only part of their interest and remains liable has made a:", "sublease", ["assignment","novation","surrender"], "Sublease."),
 ("Constructive eviction occurs when:", "the landlord's failure makes the premises uninhabitable and the tenant vacates", ["the sheriff evicts","the tenant refuses to pay","the lease expires"], "Tenant leaves."),
 ("A ground lease is typically:", "long-term", ["month-to-month","gross","residential only"], "50–99 years."),
 ("A percentage lease is common in:", "retail properties", ["farms only","single-family homes","condos"], "Based on sales."),
 ("Death of a tenant generally:", "does not automatically end the lease", ["terminates the lease","terminates the lease for life","transfers title"], "Rules vary."),
 ("A property manager is bound by:", "the management agreement", ["the MLS rules","the tenant's lease only","title insurance"], "Agency."),
 ("An estoppel certificate:", "confirms lease terms for a buyer or lender", ["creates a lease","evicts a tenant","insures title"], "Verifies terms."),
 ("The most common homeowners form for a single-family dwelling is:", "HO-3", ["HO-4","HO-6","HO-8"], "Open peril dwelling."),
 ("Homeowners flood damage is:", "excluded and requires a separate policy", ["covered","covered by title insurance","covered by PMI"], "Flood is separate."),
 ("Self-help eviction (changing locks) is generally:", "illegal", ["required","best practice","legal after a week"], "Court process."),
 ]))
